from common63 import *
a=read(OUT/'AUDIT63_V1.json');v=read(OUT/'INDEPENDENT_REPLAY63_V1.json');assert v['status']=='PASS';sources()
rows=[]
for r in a['records']:
 first,last=r['estimator_interventions'][0],r['estimator_interventions'][-1]
 rows.append({'fixture_seed':r['untrained_seed'],'auxiliary_penalty_before':first['auxiliary_penalty'],'auxiliary_penalty_zero_head':last['auxiliary_penalty'],'native_total_loss_reduction':first['native_total_loss']-last['native_total_loss'],'predictive_output_max_change':last['predictive_output_max_difference'],'missing_within_component_variance_N20':r['sample_count_law']['mean_missing_within_component_variance'],'zero_head_aux_encoder_gradient_norm':last['aux_grad_encoder_norm']})
table='| Untrained fixture seed | Native auxiliary penalty | Zero-head penalty | Predictive output change | Omitted variance at N20 |\n|---|---:|---:|---:|---:|\n'
for r in rows:table+=f"| {r['fixture_seed']} | {r['auxiliary_penalty_before']:.10f} | {r['auxiliary_penalty_zero_head']:.10f} | {r['predictive_output_max_change']:.1f} | {r['missing_within_component_variance_N20']:.7f} |\n"
scope='Three untrained initialization fixtures, four early training-region contexts each, original L96/H720 source dimensions. CPU float64. Zero trained models, zero optimizer steps, zero heldout scores. This is component qualification, not paper-performance reproduction. Raw inputs, weights and traces stay on G.'
finding='The auxiliary noise estimator can be set identically to zero without changing any reconstruction, predicted location/scale, or variational distribution in the checked same-RNG calls. Its penalty then attains its analytic global lower bound, and the auxiliary-driven gradients into both the estimator and encoder vanish. Thus this implemented penalty alone does not rule out a collapsed estimator. This is not proof that trained COFE converges to collapse or that its theoretical identifiability result is false.'
sample='At N=sample_schedule=20 the native method returns component locations and omits positive within-component observation variance. At N40 the same latent-component parameters produce Normal samples. Official ETTh1 N100 does not enter the special branch; this audit does not invalidate its published scores. Numerical differences in finite sample quantiles must be distinguished from this explicit branch changing the component law.'
retired='A different variational-training posterior and standard-normal prediction prior is not by itself a defect: it is compatible with VAE inference and the paper’s ELBO. An internal decoder translation/scale response also does not prove incorrect physical unit conversion: external global scaling and legitimate level-dependent variance must be considered. Neither observation is accepted as an independent research gap.'
decision='No new world-model research direction is established. Zero-head collapse prevention by an invertible normalized innovation density/Jacobian is established probability and flow machinery, not a new method. Do not claim novelty by adding it to this code. Before treating this source as a mechanism baseline, separate original-protocol use from any scientifically justified correction.'
reports={
'README.md':'# C63: COFE native probability/objective qualification\n\n'+scope+'\n\n'+finding+'\n\n'+sample+'\n\n'+decision+'\n',
'literature_review.md':'# Literature and innovation boundary\n\n[COFE paper](https://www.ijcai.org/proceedings/2026/0602.pdf), Sections3.1–3.3, describes variational inference and coarse/fine innovation constraints; its stated prior is standard Normal. The proof has explicit distributional assumptions. This audit does not test those assumptions on real systems. [Pinned code](https://github.com/polars8948/COFE/tree/a53409aa6d97c65b5b36b7f6b27fc5fbdb5e3df1) supplies the exact executed core and selected original loss bodies. The published Figure3 and Equation13 also differ in their displayed difference order, so naming alone is insufficient to diagnose the code’s intended coarse/fine orientation. The collapse bound below does not depend on assigning physical meaning to those labels.\n\n'+decision+'\n',
'baseline_registry.md':'# Executed source registry\n\nCOFE a53409aa6d97c65b5b36b7f6b27fc5fbdb5e3df1, MIT,12 source/config/license objects. Native COFEVAE, auxiliary Transformer, attention, transition and RevIN file bytes executed unchanged. Actual installed reformer dependency used. Namespace packages avoid unrelated framework eager imports. Original forward/loss/kld_loss AST bodies run on an attribute harness; no full Forecaster/Lightning/GluonTS pipeline was imported or trained. Config follows run.sh L96/H720 and ETTh1 YAML model dimensions. Fixture scaling uses first2048 source rows and is not author benchmark preprocessing.\n\n'+scope+'\n',
'experimental_results.md':'# Native contract audit results\n\n'+scope+'\n\n'+table+'\n\n'+finding+'\n\n'+sample+f"\n\nIndependent NumPy replay maximum arithmetic discrepancy: {v['max_arithmetic_difference']:.4g}. Every archived fixture weight and trace hash was verified.\n",
'negative_evidence.md':'# Negative evidence and rejected interpretations\n\n'+retired+'\n\n'+decision+'\n\nThe three fixtures are not trained seed replicates or independent measured systems. No causal response, forecasting improvement or calibration on heldout data was evaluated. N20 behavior cannot be transferred to official N100 scores. A correct normalized-density toy guard demonstrates an ordinary safeguard, not an executed replacement architecture.\n',
'hypothesis_space.md':'# Competing hypotheses and falsification\n\nH0: posterior/prior difference alone implies invalid inference. Rejected as a general diagnosis after reading the ELBO.\n\nH1: requested sample count changes only approximation accuracy. Refuted for the explicit N20 location-only branch, conditional on the same component list. This concerns one source interface setting.\n\nH2: the implemented auxiliary penalty excludes a zero innovation estimator. Refuted by the analytic lower bound and exact native-loss interventions at frozen predictive weights. A stronger claim about actual training or theoretical nonidentifiability remains untested.\n\nH3: the internal scale translation probe proves a universal real-world error. Not accepted: a full preprocessing contract and data-generating law are needed.\n',
'research_ideas.md':'# Research candidates\n\nThe observed auxiliary shortcut is a valid implementation/objective attribution issue. It does not independently justify a new time-series world-model framework, because invertibility and normalized innovation density provide established safeguards. Sample-count-invariant trajectory generation is an interface requirement with an ordinary repair: sample from the same complete law for every requested count. Neither repair is claimed novel.\n\n'+decision+'\n',
'final_research_direction.md':'# Current research disposition\n\n**Research Question:** Does the pinned COFE implementation’s sampling/objective code enforce its intended probability and noncollapse contracts?\n\n**Evidence:** '+scope+'\n\n'+table+'\n\n'+finding+'\n\n**Existing Methods:** Proper change-of-variables density discourages singular innovation transforms; invariant generative sampling can use the same complete observation law at every count. These are ordinary existing safeguards.\n\n**Proposed Idea:** None accepted from this audit.\n\n**Falsification:** A collapsed estimator is admissible under this implemented penalty, but that does not prove all normalized coarse/fine latent dynamics models fail. A trained control and independent mechanism would be required for a broader claim.\n\n**Feasibility:** Executed unmodified core components and exact selected original objective methods on the server CPU. No new GPU training or heldout adaptation.\n\n**Next Experiment:** Any prospective mechanism-level comparison must first include a competent normalized stochastic-state baseline and distinguish paper assumptions, original code and ordinary corrections. Do not promote this audit or a posterior/prior difference into a new framework.\n\nOverall discovery ACTIVE_UNACHIEVED; accepted final directions:0.\n'
}
for name,text in reports.items():
 with (ROOT/name).open('x',encoding='utf-8') as f:f.write(text)
summary={'utc':utc(),'status':'C63_NATIVE_CONTRACT_AUDIT_CLOSED','decision':'NO_NEW_RESEARCH_DIRECTION_ESTABLISHED','weight_fixtures':3,'trained_models':0,'optimizer_updates':0,'heldout_scores':0,'rows':rows,'independent_replay_max_error':v['max_arithmetic_difference'],'sample_count_branch_scope':'N20; official N100 does not enter it','zero_estimator_minimizes_auxiliary_penalty_without_predictive_change':True,'posterior_prior_difference_is_not_by_itself_a_bug':True,'accepted_final_directions':0}
dump(OUT/'SUMMARY63_V1.json',summary);dump(OUT/'CLOSURE63_V1.json',{'utc':utc(),'status':'CLOSED','reports':{name:sha(ROOT/name) for name in reports},'audit_sha256':sha(OUT/'AUDIT63_V1.json'),'replay_sha256':sha(OUT/'INDEPENDENT_REPLAY63_V1.json'),'summary_sha256':sha(OUT/'SUMMARY63_V1.json'),'accepted_final_directions':0,'trained_models':0})
print(json.dumps(summary))
